mapper.select:
SELECT * FROM product WHERE id IN
#{id}
ORDER BY id FOR UPDATE

mapper.update:
UPDATE product
SET stock = stock - #{quantity},
    version = version + 1
WHERE id = #{id}
  AND status = 'ON_SALE'
  AND stock >= #{quantity}

UPDATE product
SET status = #{status},
    version = version + 1
WHERE id = #{id}
  AND version = #{version}
